from pathlib import Path

BASE = Path("data/raw/2026-10-11-societal-persistence/evidence")
OLD = Path("data/raw/2026-10-11-early-indian-continuity/institutions")


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def witness(path: Path, role: str = "primary text", reused: bool = False) -> dict:
    return {"path": path.as_posix(), "sha256": sha(path), "bytes": path.stat().st_size,
            "role": role, "reused_from_prior_package": reused,
            "redistribution": "local-only; parent rights remain separate from host metadata"}


def source(sid, title, citation, year, url, lineage, read_scope, paths, notes="", dates=None):
    return {"source_id": sid, "title": title, "citation": citation,
            "publication_year": year, "publication_dates": dates or {"issue_year": year},
            "primary_url": url, "evidence_lineage": lineage,
            "reading_scope": read_scope, "inspection_status": "included; specified loci inspected",
            "witnesses": [witness(*x) for x in paths], "source_notes": notes}


