def observation(oid, sid, locus, site, context, phase, dates, dating, otype, claim,
                interpretation, significance, limits, alternatives, boundary="specified excavation context"):
    return {"observation_id": oid, "source_id": sid, "locus": locus, "site": site,
            "context": context, "phase": phase, "date_interval": dates, "dating_basis": dating,
            "observation_type": otype, "source_observation": claim,
            "author_interpretation": interpretation, "renewal_question": significance,
            "inference_limits": limits, "alternative_explanations": alternatives,
            "outcome_unit": boundary, "measured_service_delivery": None,
            "task_duration_bounds": None, "task_window": None,
            "demand_lower_bound": None, "initial_delivery_upper_bound": None,
            "imports_upper_bound": None, "provider": "not established by this observation"}


