def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("destination", type=Path)
    args = parser.parse_args()
    args.destination.mkdir(parents=True, exist_ok=True)
    outputs = [args.destination / "sources.json", args.destination / "observations.json", args.destination / "acquisition-index.json"]
    if any(p.exists() for p in outputs):
        raise SystemExit("Refusing to overwrite an existing documentary endpoint; choose a fresh destination")
    works = sources()
    obs = observations()
    source_map = {s["source_id"]: s for s in works}
    for rec in obs:
        rec["witness_hash"] = source_map[rec["source_id"]]["witnesses"][0]["sha256"]
        if rec["source_id"] == "S05":
            rec["witness_hash"] = source_map["S05"]["witnesses"][1]["sha256"]
        rec["evidence_lineage"] = source_map[rec["source_id"]]["evidence_lineage"]
    attempts = []
    for manifest in sorted(BASE.glob("acquisition-v*/acquisition.json")):
        attempts.extend({**a, "manifest": manifest.as_posix()} for a in json.loads(manifest.read_text(encoding="utf-8")))
    candidate_notes = [
        {"candidate_id": "C01", "citation": "Brad Chase. Social change at the Harappan settlement of Gola Dhoro: a reading from animal bones. Antiquity 84(324) (2010): 528–543. DOI 10.1017/S0003598X00066758.", "reading_scope": "publisher abstract/metadata only", "status": "excluded from substantive observation coding; full article unavailable in inspected access route", "witness": witness(BASE / "acquisition-v4/chase2010-publisher.html", "abstract and metadata")},
        {"candidate_id": "C02", "citation": "Valentine Roux, Blandine Bril and Gilles Dietrich. Skills and learning difficulties involved in stone knapping: The case of stone-bead knapping in Khambhat, India. World Archaeology 27(1) (1995): 63–87. DOI 10.1080/00438243.1995.9980293.", "reading_scope": "bibliographic discovery only; publisher route returned HTTP 403", "status": "excluded; no apprentice duration or performance claim coded"},
    ]
    access_notes = [
        "Several filenames ending .pdf contain access-challenge HTML; signature checks exclude them as source texts.",
        "acquisition-v2/bisht2015-full.pdf is a modern interpretive wrapper with selected ASI images and rebus claims; it is excluded as a primary report witness.",
        "An early adjacent manual .txt derivative of the Dholavira mirror selected the wrong node. The preserved extract-v1/01-bisht2015-report-mirror.txt is the correct longest transcription; original PDF now controls substantive claims.",
        "Official legacy/current full-report routes returned 404; archive original was subsequently acquired without disabling TLS verification.",
        "Archive IIIF image routes failed verified-TLS hostname checks. Original PDF pages were rendered locally instead.",
        "Existing earlier craft witnesses are read in place and not recopied or relabeled as new independent evidence.",
    ]
    payloads = [
        {"schema_version": "1.0", "frozen_date": "2026-10-11", "scope": "purposive documentary application; no fitted archaeological model", "included_primary_works": works, "excluded_candidates": candidate_notes, "access_notes": access_notes},
        {"schema_version": "1.0", "frozen_date": "2026-10-11", "scope": "authored source-linked observations, with measurement gates left unresolved", "observations": obs},
        {"schema_version": "1.0", "attempts": attempts},
    ]
    for path, payload in zip(outputs, payloads):
        path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"included_primary_works": len(works), "excluded_candidates": len(candidate_notes), "observations": len(obs), "new_acquisition_attempts": len(attempts)}))


if __name__ == "__main__":
    main()
